import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易集注 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易集注 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/048.md","filePath":"zh/classics/jizhu/048.md"}'),h={name:"zh/classics/jizhu/048.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>姤，遇也，五月之卦也。一阴生于下，阴与阳遇，以其本非所望，而卒然值之，如不期而遇者，故为姤也。《序卦》：夬决也，决必有所遇，故受之以姤，所以次夬。</p><p>一阴而遇五阳，有女壮之象，故戒占者勿用取女。以其女德不贞，决不能长久，从一而终也。幽王之得褒姒，高宗之立武昭仪，养鹙弃鹤，皆出于一时一念之差，而岂知后有莫大之祸哉。故一阴生于五阳之下，阴至微矣。而圣人即曰女壮勿用取者，防其渐也。</p><p>《彖》曰：姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉!</p><p>释卦名卦辞，而极赞之。取妻非一朝一夕之事，故曰夫妇之道，不可以不久也。不可与长者，言女壮，则女德不贞，不能从一而长久也。上五阳天也，下一阴地也。品物咸亨者，万物相见乎离。亨，嘉之会也。天地相遇，止可言资始资生，而曰咸章者，品物在五月，皆章美也。刚指九二，刚遇中正者，九二之阳德，遇乎九五之中正也。遇乎中正，则明良会而庶事康，其道可大行于天下矣。姤本不善，圣人义理无穷，故又以其中之善者言之。言一阴而遇五阳，勿用取女，固不善矣。然天之遇地，君之遇臣，又有极善者存乎其中焉。以一遇之间，而有善不善，可见世之或治或乱，事之或成或败，人之或穷或通，百凡天下国家之事，皆不可以智力求之，惟其遇而已矣。时当相遇，莫之为而为，莫之致而至，遇之时义，不其大矣哉。</p><h3 id="《象》曰-天下有风-姤-后以施命诰四方。" tabindex="-1">《象》曰：天下有风，姤，后以施命诰四方。 <a class="header-anchor" href="#《象》曰-天下有风-姤-后以施命诰四方。" aria-label="Permalink to “《象》曰：天下有风，姤，后以施命诰四方。”">​</a></h3><p>风行天下，物无不遇，姤之象也。施命者，施命令于天下也。兴利除害，皆其命令之事也。诰者告也，晓谕警戒之意。君门深于九重，堂陛远于万里，岂能与民相遇，惟施命诰四方，则与民相遇，亦犹天之风与物相遇也。干为君，后之象。又为言，诰之象。又错坤，方之象，巽乃命之象。</p><p>初六，系于金柅，贞吉。有攸往，见凶，羸豕孚蹢躅。柅女履反，蹢音的，躅直录反</p><p>柅者，收丝之具也。金者，籰上孔，用金也，今人多以铜钱为之。巽为木，柅之象也;又为绳，系之象也。变干，金之象也。贞吉者，言系于金柅，前无所往，则得其正而吉也。若无所系，有所攸往，往而相遇相比之二，正应之四，则立见其凶也。羸豕者，小豕也。孚者诚也。蹢躅者，跳踯缠绵也。言小豕相遇乎豕，即孚契蹢躅，不肯前进，此立见其凶，可丑之象也。凡阴爻居下卦者，不可皆以为小人害君子。如姤有相遇之义，观有观示之义，此卦因以为小人害君子，所以将九五极好之爻通说坏了。</p><p>初六一阴始生，当遇之时，阴不当往遇乎阳，故教占者有系于金柅之象。能如此，则正而吉矣。若有所往，立见其凶。故又有羸豕蹢躅之象，其戒深矣。</p><h3 id="《象》曰-系于金柅-柔道牵也。" tabindex="-1">《象》曰：系于金柅，柔道牵也。 <a class="header-anchor" href="#《象》曰-系于金柅-柔道牵也。" aria-label="Permalink to “《象》曰：系于金柅，柔道牵也。”">​</a></h3><p>牵者牵连也，阴柔牵乎阳，所以戒其往。</p><p>九二，包有鱼，无咎，不利宾。</p><p>包者包裹也，详见蒙卦九二。鱼阴物又美，初之象也。剥变巽曰贯鱼，井曰射鲋，姤曰包鱼，皆以巽为少女，取象于阴物之美也。言二包裹缠绵乎初，犹包鱼也。无咎者，本卦主于相遇，故无咎也。不利宾者，理不当奉及于宾也。盖五月包裹之鱼，必馁而臭矣，所以不利于宾也。巽为臭，鱼臭不及宾之象也。五阳缠绵一阴，故于四爻、五爻皆取包裹之象。无咎，以卦名取义，不及宾，以鱼取义。若以正意论，初与四为正应，二既先包乎初，则二为主，而四为宾矣，所以不利宾。而四包无鱼，但易以象为主，故只就鱼上说。</p><p>九二与初，本非正应，彼此皆欲相遇，乃不正之遇也，故有五月包鱼之象。占者得此，仅得无咎，然不正之遇，已不可达及于宾矣，故不利宾。</p><h3 id="《象》曰-包有鱼-义不及宾也。" tabindex="-1">《象》曰：包有鱼，义不及宾也。 <a class="header-anchor" href="#《象》曰-包有鱼-义不及宾也。" aria-label="Permalink to “《象》曰：包有鱼，义不及宾也。”">​</a></h3><p>五月包鱼，岂可及宾，以义揆之，不可及宾也。</p><p>九三，臀无肤，其行次且，厉，无大咎。</p><p>夬之九四与姤相综倒转即姤之九三，所以爻辞同。</p><p>九三当遇之时，过刚不中，隔二，未牵连乎初相遇之难，故有此象。然不相遇，则亦无咎矣。故占者虽危厉，而无大咎也。</p><h3 id="《象》曰-其行次且-行未牵也。" tabindex="-1">《象》曰：其行次且，行未牵也。 <a class="header-anchor" href="#《象》曰-其行次且-行未牵也。" aria-label="Permalink to “《象》曰：其行次且，行未牵也。”">​</a></h3><p>本卦主于相遇，三其行未得与初牵连，所以次且。</p><p>九四，包无鱼，起凶。</p><p>初六不中不正，卦辞以女壮勿取戒之矣。若屯卦六二与初相比，不从乎初，十年乃字，盖六二柔顺中正故也。今不中正，所以舍正应而从二，既从乎二，则民心已离矣。九四才虽刚而位则柔，据正应之理，起而与二相争，亦犹三国之争荆州，干戈无宁日也，岂不凶。故不曰凶，而曰起凶，如言起衅也。</p><p>九四不中不正，当遇之时，与初为正应。初为二所包，故有包无鱼之象。九四不平，与二争之，岂不起其凶哉，故其象占如此。</p><h3 id="《象》曰-无鱼之凶-远民也。" tabindex="-1">《象》曰：无鱼之凶，远民也。 <a class="header-anchor" href="#《象》曰-无鱼之凶-远民也。" aria-label="Permalink to “《象》曰：无鱼之凶，远民也。”">​</a></h3><p>阴为民，民之象也。故观卦下阴爻曰观民，二近民而四远民也。</p><p>九五，以杞包瓜，含章，有陨自天。</p><p>杞，枸杞也，杞与瓜皆五月所有之物。干为果，瓜之象也。因前爻有包鱼之包，故此爻亦以包言之。含章者，含藏其章美也。此爻变离，有文明章美之意。又居中，有包含之意，故曰含章。含即杞之包，章即瓜之美。以杞包瓜，即含章之象也。陨者从高而下也，有陨自天者，言人君之命令，自天而降下也。巽为命，乾为天，故命令自天而降。孔子后以施命诰四方一句，本自周公有陨自天来，故《小象》曰，志不违命。且此爻变成鼎，又正位凝命之君，三个命字可证。</p><p>九五当变之时，有中正之德，深居九重，本不与民相遇，故有以杞包瓜，含藏章美之象。然含藏中正之章美，不求与民相遇，及施命诰四方，如自天而降，亦犹天下之风，无物不相遇也，其相遇之大为何如哉。占者有是德，方应是占也。</p><h3 id="《象》曰-九五含章-中正也-有陨自天-志不舍命也。舍音舍" tabindex="-1">《象》曰：九五含章，中正也;有陨自天，志不舍命也。舍音舍 <a class="header-anchor" href="#《象》曰-九五含章-中正也-有陨自天-志不舍命也。舍音舍" aria-label="Permalink to “《象》曰：九五含章，中正也;有陨自天，志不舍命也。舍音舍”">​</a></h3><p>有中正之德，所以舍其中正之章美，不发露也。志者心志也，舍违也，命者命令也。虽不发露章美，然心志不违，施命诰四方，所以有陨自天。</p><p>上九，姤其角，吝无咎。</p><p>与晋其角同，当遇之时，高亢遇刚，不遇于初，故有姤其角之象，吝之道也。然不近阴私，亦无咎矣，故其占如此。</p><h3 id="《象》曰-姤其角-上穷吝也。" tabindex="-1">《象》曰：姤其角，上穷吝也。 <a class="header-anchor" href="#《象》曰-姤其角-上穷吝也。" aria-label="Permalink to “《象》曰：姤其角，上穷吝也。”">​</a></h3><p>居上卦之极，故穷，惟穷所以吝。</p>',36)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
